    /// <summary>
    /// Returns reactions, which can be added to a message. The list can change after updateActiveEmojiReactions, updateChatAvailableReactions for the chat, or updateMessageInteractionInfo for the message
    /// </summary>
    public Task<TdLib.TdApi.Objects.AvailableReactions> GetMessageAvailableReactionsAsync(long chatId = default, long messageId = default, int rowSize = default)
    {

           using var activity =  StartCallActivity("GetMessageAvailableReactionsAsync", typeof(GetMessageAvailableReactions).FullName ?? "GetMessageAvailableReactionsAsync");

           try
           {
             return client.GetMessageAvailableReactionsAsync(chatId, messageId, rowSize);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
